  4	/**
  5	 * In-place ascending sort for integer arrays using heap sort.
  6	 */
  7	public final class HeapSort {
  8	
  9	    private HeapSort() {
 10	        // Utility class; do not instantiate.
 11	    }
 12	
 13	    /**
 14	     * Sorts the supplied array in ascending order.
 15	     *
 16	     * @param values array to sort
 17	     * @throws NullPointerException if {@code values} is null
 18	     */
 19	    public static void sort(int[] values) {
 20	        Objects.requireNonNull(values, "values");
 21	        sort(values, 0, values.length);
 22	    }
 23	
 24	    /**
 25	     * Sorts the specified range of the supplied array in ascending order.
 26	     * The range is {@code [fromIndex, toIndex)}.
 27	     *
 28	     * @param values array to sort
 29	     * @param fromIndex inclusive start of the range
 30	     * @param toIndex exclusive end of the range
 31	     * @throws NullPointerException if {@code values} is null
 32	     * @throws IndexOutOfBoundsException if the range is invalid
 33	     */
 34	    public static void sort(int[] values, int fromIndex, int toIndex) {
 35	        Objects.requireNonNull(values, "values");
 36	        Objects.checkFromToIndex(fromIndex, toIndex, values.length);
 37	
 38	        if (toIndex - fromIndex < 2) {
 39	            return;
 40	        }
 41	
 42	        new RangeHeap(values, fromIndex, toIndex).sort();
 43	    }
 44	
 45	    /**
 46	     * Returns a sorted copy of the supplied array.
 47	     *
 48	     * @param values array to copy and sort
 49	     * @return a new sorted array
 50	     * @throws NullPointerException if {@code values} is null
 51	     */
 52	    public static int[] sortedCopy(int[] values) {
 53	        Objects.requireNonNull(values, "values");
 54	
 55	        int[] copy = Arrays.copyOf(values, values.length);
 56	        sort(copy);
 57	        return copy;
 58	    }
 59	
 60	    private static final class RangeHeap {
 61	        private final int[] values;
 62	        private final int baseIndex;
 63	        private final int heapSize;
 64	
 65	        private RangeHeap(int[] values, int baseIndex, int toIndex) {
 66	            this.values = values;
 67	            this.baseIndex = baseIndex;
 68	            this.heapSize = toIndex - baseIndex;
 69	        }
 70	
 71	        private void sort() {
 72	            buildMaxHeap();
 73	
 74	            for (int end = heapSize - 1; end > 0; end--) {
 75	                swap(0, end);
 76	                siftDown(0, end);
 77	            }
 78	        }
 79	
 80	        private void buildMaxHeap() {
 81	            for (int root = heapSize / 2 - 1; root >= 0; root--) {
 82	                siftDown(root, heapSize);
 83	            }
 84	        }
 85	
 86	        private void siftDown(int rootIndex, int heapLimit) {
 87	            int current = rootIndex;
 88	
 89	            while (true) {
 90	                int leftChild = leftChildIndex(current);
 91	                if (leftChild >= heapLimit) {
 92	                    return;
 93	                }
 94	
 95	                int rightChild = leftChild + 1;
 96	                int largestChild = leftChild;
 97	
 98	                if (rightChild < heapLimit && valueAt(rightChild) > valueAt(leftChild)) {
 99	                    largestChild = rightChild;
100	                }
101	
102	                if (valueAt(current) >= valueAt(largestChild)) {
103	                    return;
104	                }
105	
106	                swap(current, largestChild);
107	                current = largestChild;
108	            }
109	        }
110	
111	        private int leftChildIndex(int relativeIndex) {
112	            return 2 * relativeIndex + 1;
113	        }
114	
115	        private int valueAt(int relativeIndex) {
116	            return values[baseIndex + relativeIndex];
117	        }
118	
119	        private void swap(int firstRelativeIndex, int secondRelativeIndex) {
120	            int firstIndex = baseIndex + firstRelativeIndex;
121	            int secondIndex = baseIndex + secondRelativeIndex;
122	            int temp = values[firstIndex];
123	            values[firstIndex] = values[secondIndex];
124	            values[secondIndex] = temp;
125	        }
126	    }
127	}

